    const olim=ol&0x7e7e7e7e;
    const ohim=oh&0x7e7e7e7e;
    let fh=ohim&((ph<<9)|(pl>>>23));
    let fl=olim&(pl<<9);
    fh|=ohim&((fh<<9)|(fl>>>23));
    fl|=olim&(fl<<9);
    let f2h=ohim&((ohim<<9)|(olim>>>23));
    let f2l=olim&(olim<<9);
    fh|=f2h&((fh<<18)|(fl>>>14));
    fl|=f2l&(fl<<18);
    fh|=f2h&((fh<<18)|(fl>>>14));
    fl|=f2l&(fl<<18);
    rl|=(fl<<9); rh|=((fh<<9)|(fl>>>23));
    let bl=olim&((pl>>>9)|(ph<<23));
    let bh=ohim&(ph>>>9);
    bl|=olim&((bl>>>9)|(bh<<23));
    bh|=ohim&(bh>>>9);
    let b2l=olim&((olim>>>9)|(ohim<<23));
    let b2h=ohim&(ohim>>>9);
